.ds-nocturne { --ds-cover-bg: radial-gradient(ellipse 70% 80% at 62% 42%, var(--ds-night-raised), var(--ds-night) 100%);
  --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-lamp); --ds-hand-fill2: var(--ds-cool); --ds-hand-muted: var(--ds-night-sunk); --ds-hand-ground: var(--ds-night-raised); --ds-hand-stroke: 1.5; --ds-hand-cap: round; --ds-hand-bg: radial-gradient(ellipse 70% 80% at 50% 40%, var(--ds-night-raised), var(--ds-night) 100%);
  --ds-tpl-edge: 1px solid var(--ds-line); --ds-tpl-radius: 2px; --ds-tpl-rule: 1px solid var(--ds-line); --ds-tag-radius: 999px;
  --ds-slide-bg: var(--ds-night-raised); --ds-slide-fg: var(--ds-ink); --ds-slide-title-bg: radial-gradient(ellipse 80% 90% at 50% 30%, var(--ds-night-raised), var(--ds-night) 100%); --ds-slide-title-fg: var(--ds-ink);
  --ds-slide-split-a: var(--ds-lamp); --ds-slide-split-a-fg: var(--ds-on-lamp); --ds-slide-split-b: var(--ds-cool); --ds-slide-split-b-fg: var(--ds-night);
  --ds-hero-bg: radial-gradient(ellipse 60% 90% at 70% 50%, var(--ds-night-raised), var(--ds-night) 100%); }
.ds-nocturne .ds-section h2, .ds-nocturne .ds-cover-name { font-family: var(--font-display); font-weight: 300; letter-spacing: -.02em; }
.ds-nocturne .ds-eyebrow, .ds-nocturne .ds-chip, .ds-nocturne .t-caps { font-family: "Cinzel", Georgia, serif; letter-spacing: .26em; text-transform: uppercase; font-size: 11px; font-weight: 500; }
.ds-nocturne .ds-chip { border-radius: 999px; padding: 5px 12px; }
.ds-nocturne .ds-cover-tag { color: var(--ds-ink-soft); font-weight: 300; font-size: 22px; }
.ds-nocturne .ds-tpl-slide-h, .ds-nocturne .ds-tpl-hero-h, .ds-nocturne .ds-tpl-ed-h { font-weight: 300; letter-spacing: -.02em; }
.ds-nocturne .ds-tpl-slide-big { font-family: var(--font-mono); font-weight: 500; color: var(--ds-lamp); text-shadow: var(--ds-glow-text); }
.ds-nocturne .ds-tpl-brand { font-family: "Cinzel", Georgia, serif; font-weight: 500; letter-spacing: .2em; font-size: 14px; text-transform: uppercase; }
.ds-nocturne .ds-tpl-pull-n { font-family: var(--font-mono); color: var(--ds-lamp); } .ds-nocturne .ds-tpl-dropcap { font-weight: 300; color: var(--ds-lamp); }
.ds-nocturne .ds-tpl-kicker { font-family: "Cinzel", Georgia, serif; letter-spacing: .26em; font-size: 11px; }
.ds-nocturne .ds-tpl-tag { font-family: var(--font-mono); letter-spacing: .12em; }
.ds-nocturne .h-glow .h-ink { opacity: .32; } .light .ds-nocturne .h-glow .h-ink { opacity: .16; }
.ds-nocturne .h-text { paint-order: stroke; stroke: var(--ds-night); stroke-width: 3px; stroke-linejoin: round; }
.ds-nocturne .h-num { font-family: var(--font-display); font-weight: 300; font-size: 46px; fill: var(--ds-lamp); letter-spacing: -.02em; }
.ds-nocturne .n-night { fill: var(--ds-night); } .ds-nocturne .n-star circle { fill: var(--ds-ink); opacity: .55; } .light .ds-nocturne .n-star circle { opacity: 0; }
.ds-nocturne .n-pool-in { stop-color: var(--ds-night-raised); } .ds-nocturne .n-pool-out { stop-color: var(--ds-night); }
.ds-nocturne .n-lit { fill: var(--ds-lamp); } .ds-nocturne .n-dark { fill: var(--ds-night-sunk); stroke: var(--ds-line); stroke-width: 1; }
.ds-nocturne .n-ribbon { fill: var(--ds-ember); } .ds-nocturne .n-tally line { stroke: var(--ds-ink); stroke-width: 2; stroke-linecap: round; }
.ds-nocturne .n-svg-label { font-family: var(--font-mono); font-size: 11px; letter-spacing: .14em; fill: var(--ds-ink-muted); } .ds-nocturne .n-svg-caps { font-family: "Cinzel", Georgia, serif; font-size: 11px; letter-spacing: .26em; fill: var(--ds-ink-muted); } .ds-nocturne .n-lamp-fill { fill: var(--ds-lamp); }
.ds-nocturne .n-svg-big { font-family: var(--font-display); font-weight: 300; font-size: 64px; letter-spacing: -.03em; fill: var(--ds-lamp); }
.ds-nocturne .n-caps { color: var(--ds-ink-muted); margin: 0 0 12px; display: flex; align-items: center; gap: 12px; } .ds-nocturne .n-kicker-rule { display: inline-block; width: 34px; height: 1px; background: currentColor; }
.ds-nocturne .n-em { font-style: italic; font-weight: 400; color: var(--ds-lamp-hot); text-shadow: var(--ds-glow-text); }
.ds-nocturne .n-btn { font-family: "Cinzel", Georgia, serif; font-size: 12px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; line-height: 18px; padding: 11px 18px; border: 1px solid var(--ds-ink); border-radius: 2px; background: transparent; color: var(--ds-ink); cursor: pointer; transition: box-shadow 300ms ease, background 200ms ease; }
.ds-nocturne .n-btn:hover { background: var(--ds-lamp-soft); } .ds-nocturne .n-btn:focus-visible { outline: 2px solid var(--ds-ember); outline-offset: 2px; }
.ds-nocturne .n-btn-primary { background: var(--ds-lamp); color: var(--ds-on-lamp); border-color: var(--ds-lamp); } .ds-nocturne .n-btn-primary:hover { background: var(--ds-lamp); box-shadow: var(--ds-halo); }
.ds-nocturne .n-tag { display: inline-flex; gap: 6px; padding: 3px 10px; border-radius: 999px; border: 1px solid var(--ds-line); font-family: var(--font-mono); font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: var(--ds-ink-muted); }
.ds-nocturne .n-tag-lit { color: var(--ds-lamp); border-color: var(--ds-lamp); background: var(--ds-lamp-soft); } .ds-nocturne .n-tag-caution { color: var(--ds-caution); border-color: var(--ds-caution); } .ds-nocturne .n-tag-positive { color: var(--ds-positive); border-color: var(--ds-positive); }
.ds-nocturne .n-stat { display: grid; gap: 6px; padding: 18px 20px; border: 1px solid var(--ds-line); border-radius: 2px; background: var(--ds-night-raised); min-width: 180px; } .ds-nocturne .n-stat-lit { box-shadow: var(--ds-halo); border-color: var(--ds-lamp); } .ds-nocturne .n-stat-lit .t-numeral { color: var(--ds-lamp); }
.ds-nocturne .n-note { font-size: 13px; color: var(--ds-ink-muted); } .ds-nocturne .ds-stats { gap: 16px; }
.ds-nocturne .n-callout { padding: 14px 18px; border-left: 2px solid var(--ds-line); font-size: 16px; line-height: 1.55; background: var(--ds-night-raised); } .ds-nocturne .n-callout strong { font-weight: 500; }
.ds-nocturne .n-callout-caution { border-left-color: var(--ds-caution); background: var(--ds-caution-soft); } .ds-nocturne .n-callout-lit { border-left-color: var(--ds-lamp); background: var(--ds-lamp-soft); }
.ds-nocturne .n-margin { display: grid; grid-template-columns: 20px 1fr; gap: 8px; margin: 0; padding: 4px 0 0; font-style: italic; font-size: 15px; line-height: 22px; color: var(--ds-ink-soft); max-width: 36ch; } .ds-nocturne .n-margin-n { font-family: var(--font-mono); font-style: normal; font-size: 11px; color: var(--ds-lamp); padding-top: 3px; }
.ds-nocturne .n-pool { background: radial-gradient(ellipse 80% 90% at 50% 30%, var(--ds-night-raised), var(--ds-night) 100%); }
.ds-nocturne .n-card { padding: 24px; border: 1px solid var(--ds-line); border-radius: 2px; transition: box-shadow 300ms ease; } .ds-nocturne .n-card:hover { box-shadow: var(--ds-halo); }
.ds-nocturne .n-card h3 { margin: 4px 0 0; } .ds-nocturne .n-card-p { margin: 10px 0 0; line-height: 1.6; color: var(--ds-ink-soft); max-width: 56ch; }
.ds-nocturne .n-cells { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 16px; } .ds-nocturne .n-cells i { display: block; width: 28px; height: 20px; border-radius: 1px; background: var(--ds-night-sunk); border: 1px solid var(--ds-line); } .ds-nocturne .n-cells .n-cell-lit { background: var(--ds-lamp); border-color: var(--ds-lamp); }
.ds-nocturne .n-cells-lg i { width: 36px; height: 26px; } .ds-nocturne .n-hud { display: block; margin: 12px 0 0; color: var(--ds-ink-muted); }
.ds-nocturne .n-sample { background: var(--ds-night); padding: 48px 20px 64px; border-top: 1px solid var(--ds-line); border-bottom: 1px solid var(--ds-line); } .ds-nocturne .n-sample-in { max-width: 1100px; margin: 0 auto; }
.ds-nocturne .n-sample-grid { display: grid; gap: 32px; align-items: center; } .ds-nocturne .n-sample-h { margin: 0; max-width: 14ch; } .ds-nocturne .n-sample-lede { margin-top: 24px; max-width: 46ch; color: var(--ds-ink-soft); }
.ds-nocturne .n-folio { display: block; margin-top: 24px; color: var(--ds-ink-muted); } .ds-nocturne .n-stat-row { display: grid; gap: 12px; margin-top: 28px; }
.ds-nocturne .n-sample-fig { padding: 28px; border: 1px solid var(--ds-line); border-radius: 2px; box-shadow: var(--ds-halo); } .ds-nocturne .n-big { font-family: var(--font-display); font-weight: 300; font-size: clamp(64px, 8vw, 112px); line-height: .9; letter-spacing: -.03em; color: var(--ds-lamp); text-shadow: var(--ds-glow-text); } .ds-nocturne .n-big-cap { margin: 14px 0 0; font-size: 16px; line-height: 1.5; color: var(--ds-ink-soft); max-width: 36ch; }
.ds-nocturne .n-sample-bottom { display: grid; gap: 24px; margin-top: 40px; } .ds-nocturne .n-panel { padding: 20px; border: 1px solid var(--ds-line); border-radius: 2px; background: var(--ds-night-raised); min-width: 0; }
@container (min-width: 760px) { .ds-nocturne .n-sample { padding: 64px 40px 80px; } .ds-nocturne .n-sample-grid { grid-template-columns: 1.1fr 1fr; } .ds-nocturne .n-stat-row { grid-template-columns: 1fr 1fr 1fr; } .ds-nocturne .n-sample-bottom { grid-template-columns: 1fr 1fr; } }
